<?php function redirect(string $p):never{header('Location:'.$p);exit;} function flash(string $t,string $m):void{$_SESSION['flash']=['type'=>$t,'message'=>$m];} function get_flash():?array{$f=$_SESSION['flash']??null;unset($_SESSION['flash']);return$f;} function valid_url(string $u):bool{$s=strtolower((string)parse_url($u,PHP_URL_SCHEME));return(bool)filter_var($u,FILTER_VALIDATE_URL)&&in_array($s,['http','https'],true);} function unique_code(PDO $db):string{$c='';do{$chars='abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789';$c='';for($i=0;$i<7;$i++)$c.=$chars[random_int(0,strlen($chars)-1)];$q=$db->prepare('SELECT id FROM links WHERE short_code=?');$q->execute([$c]);}while($q->fetch());return$c;} function base_url():string{global$config;return rtrim($config['app']['base_url'],'/');}